// Downloads the MIT-licensed "Pixelated MS Sans Serif" faces from the 98.css
// project and inlines them as base64 @font-face blocks into
// lib/src/win95_font.dart, so the Windows 95 theme renders in its authentic
// pixel font offline with no external font request.
//
// Usage: node tool/bundle_font.js
const https = require('https');
const fs = require('fs');
const path = require('path');

function get(url) {
  return new Promise((resolve, reject) => {
    https
      .get(url, { headers: { 'User-Agent': 'arcane-jaspr-win95' } }, (res) => {
        if (
          res.statusCode >= 300 &&
          res.statusCode < 400 &&
          res.headers.location
        ) {
          res.resume();
          return get(new URL(res.headers.location, url).toString()).then(
            resolve,
            reject
          );
        }
        if (res.statusCode !== 200) {
          res.resume();
          return reject(new Error('HTTP ' + res.statusCode + ' for ' + url));
        }
        const chunks = [];
        res.on('data', (c) => chunks.push(c));
        res.on('end', () => resolve(Buffer.concat(chunks)));
      })
      .on('error', reject);
  });
}

async function main() {
  const base = 'https://unpkg.com/98.css/dist/';
  const regular = await get(base + 'ms_sans_serif.woff2');
  const bold = await get(base + 'ms_sans_serif_bold.woff2');
  const b64r = regular.toString('base64');
  const b64b = bold.toString('base64');

  const face = (b64, weight) =>
    "@font-face{font-family:'Pixelated MS Sans Serif';" +
    'src:url(data:font/woff2;base64,' +
    b64 +
    ") format('woff2');font-weight:" +
    weight +
    ';font-style:normal;font-display:swap;}';

  const css = face(b64r, 400) + face(b64b, 700);

  const dart =
    "/// Embedded Windows 95 UI font faces (Pixelated MS Sans Serif, MIT 98.css).\n" +
    '///\n' +
    '/// Generated by tool/bundle_font.js. Base64 @font-face blocks so the theme\n' +
    '/// renders in its authentic pixel font offline, with no external request.\n' +
    'library;\n\n' +
    "const String win95FontFaces = r'''" +
    css +
    "''';\n";

  const out = path.join(__dirname, '..', 'lib', 'src', 'win95_font.dart');
  fs.writeFileSync(out, dart);
  console.log(
    'WROTE ' +
      out +
      ' (regular ' +
      regular.length +
      'B, bold ' +
      bold.length +
      'B)'
  );
}

main().catch((e) => {
  console.error('FONT_BUNDLE_FAILED: ' + e.message);
  process.exit(1);
});
